SELECT "PROCESS_TYPE" AS "PROCESS_TYPE", QUANTILE_CONT("JOB_DURATION_d", 0.95 ORDER BY "JOB_DURATION_d") AS p95, MEDIAN("JOB_DURATION_d") AS median, count(DISTINCT "SEQUENCE_ID") AS "COUNT_DISTINCT(SEQUENCE_ID)" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' GROUP BY "PROCESS_TYPE" 
 LIMIT 100;